WITH w AS (SELECT mktcode,tgtcode,bizdate,lastPx/10000.0 AS px,MIN(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS lo,MAX(lastPx/10000.0) OVER(PARTITION BY mktcode,tgtcode ORDER BY bizdate ROWS BETWEEN 9 PRECEDING AND CURRENT ROW) AS hi FROM `newzl`.`hsj_stock_hq_basic`) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND CASE WHEN px IS NULL OR lo IS NULL OR hi IS NULL THEN NULL WHEN px<=lo THEN '最低' WHEN px>=hi THEN '最高' WHEN (px-lo)/NULLIF(hi-lo,0)<=0.25 THEN '低' WHEN (px-lo)/NULLIF(hi-lo,0)>=0.75 THEN '高' ELSE '中' END='最高';
